# Revalidate the saved program against every kept demonstration, then persist global task memory.
spec = importlib.util.spec_from_file_location(tid, py)
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
kept = json.loads(js.read_text())
verified = all(mod.transform(p['input']) == p['output'] for p in kept)
assert verified
memory_text = f"Library files: {py} and {js}. Program reproduces every kept pair ({len(kept)} pairs): {verified}."
try:
    existing = rlm.harness.get_memory(tid)
except Exception:
    existing = None
try:
    if existing:
        rlm.harness.update_memory(tid, content=memory_text, global_=True)
    else:
        rlm.harness.create_memory(name=tid, content=memory_text, global_=True)
except Exception as e:
    print('memory operation:', type(e).__name__, str(e))
print('validated', len(kept), 'pairs; files:', py.exists(), js.exists())
